const sfx={c:null,v:.5,m:false,init(){if(this.c)return;try{this.c=new(window.AudioContext||window.webkitAudioContext)();if(this.c.state==='suspended')this.c.resume();}catch(e){}},t(f,d,ty,vl){if(!this.c||this.m)return;try{if(this.c.state==='suspended')this.c.resume();const o=this.c.createOscillator(),g=this.c.createGain();o.type=ty||"sine";o.frequency.value=f;g.gain.setValueAtTime((vl||.5)*this.v*.3,this.c.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.c.currentTime+d);o.connect(g);g.connect(this.c.destination);o.start();o.stop(this.c.currentTime+d);}catch(e){}},click(){this.init();this.t(800,.08);},grab(){this.init();this.t(700,.1);setTimeout(()=>this.t(900,.08),50);},trap(){this.init();this.t(200,.35,"sawtooth",.5);setTimeout(()=>this.t(150,.3,"sawtooth",.4),120);},lvl(){this.init();[523,587,659,784].forEach((f,i)=>setTimeout(()=>this.t(f,.2),i*120));},win(){this.init();[523,659,784,1047,1319].forEach((f,i)=>setTimeout(()=>this.t(f,.35,"sine",.6),i*130));},fail(){this.init();[300,200,150].forEach((f,i)=>setTimeout(()=>this.t(f,.3,"sawtooth",.5),i*200));},ok(y){this.init();this.t(y?880:220,.2,y?"sine":"sawtooth",.4);},sq(i){this.init();this.t([523,659,784,988][i],.25);},match(){this.init();this.t(523,.12);setTimeout(()=>this.t(659,.12),100);setTimeout(()=>this.t(784,.2),200);},tick(){this.init();this.t(1200,.06,"square",.3);},coin(){this.init();this.t(1400,.05,"sine",.2);}};
function getStars(s){if(s>=70)return 3;if(s>=45)return 2;if(s>=20)return 1;return 0;}
const CSS=`@keyframes pu{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}@keyframes su{0%{opacity:0;transform:translateY(30px)}100%{opacity:1;transform:translateY(0)}}@keyframes glow{0%,100%{box-shadow:0 0 20px rgba(229,57,53,.3)}50%{box-shadow:0 0 40px rgba(229,57,53,.6)}}@keyframes fbt{0%{transform:translateY(0) scale(1)}50%{transform:translateY(-14px) scale(1.04)}100%{transform:translateY(0) scale(1)}}@keyframes cfl{0%{transform:translateY(-10px) rotate(0);opacity:1}100%{transform:translateY(100vh) rotate(720deg);opacity:0}}@keyframes starPop{0%{transform:scale(0) rotate(-30deg);opacity:0}60%{transform:scale(1.3) rotate(5deg);opacity:1}100%{transform:scale(1) rotate(0);opacity:1}}@keyframes victoryIn{0%{transform:scale(.5) translateY(-40px);opacity:0}100%{transform:scale(1) translateY(0);opacity:1}}@keyframes victoryOut{0%{transform:scale(1);opacity:1}100%{transform:scale(.8) translateY(-30px);opacity:0}}*{box-sizing:border-box;margin:0;padding:0}html,body,#root{min-height:100vh}`;
