function TrophySVG({size=32}){return(<svg width={size} height={size} viewBox="0 0 64 64" fill="none"><defs><linearGradient id="tg1" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#FFD700"/><stop offset="50%" stopColor="#FFA000"/><stop offset="100%" stopColor="#FF8F00"/></linearGradient><linearGradient id="ts1" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#FFE082"/><stop offset="100%" stopColor="#FFB300"/></linearGradient></defs><ellipse cx="32" cy="58" rx="14" ry="4" fill="#B8860B" opacity=".3"/><rect x="26" y="52" width="12" height="6" rx="2" fill="url(#ts1)" stroke="#B8860B" strokeWidth="1"/><rect x="22" y="56" width="20" height="4" rx="2" fill="url(#ts1)" stroke="#B8860B" strokeWidth="1"/><rect x="29" y="40" width="6" height="14" rx="2" fill="url(#tg1)" stroke="#B8860B" strokeWidth=".8"/><path d="M14 8H50V12C50 28 42 38 32 40 22 38 14 28 14 12Z" fill="url(#tg1)" stroke="#B8860B" strokeWidth="1.5"/><path d="M14 14C10 14 6 18 6 24 6 30 10 32 14 30" fill="url(#ts1)" stroke="#B8860B" strokeWidth="1"/><path d="M50 14C54 14 58 18 58 24 58 30 54 32 50 30" fill="url(#ts1)" stroke="#B8860B" strokeWidth="1"/></svg>);}
function GiftSVG({size=32,locked=true}){return(<svg width={size} height={size} viewBox="0 0 48 48" fill="none"><defs><linearGradient id="gb1" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={locked?"#888":"#E53935"}/><stop offset="100%" stopColor={locked?"#555":"#B71C1C"}/></linearGradient><linearGradient id="gr1" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={locked?"#aaa":"#FFD700"}/><stop offset="100%" stopColor={locked?"#777":"#DAA520"}/></linearGradient></defs><rect x="4" y="18" width="40" height="26" rx="4" fill="url(#gb1)" stroke={locked?"#666":"#8B0000"} strokeWidth="1.5"/><rect x="2" y="14" width="44" height="10" rx="3" fill="url(#gr1)" stroke={locked?"#666":"#B8860B"} strokeWidth="1.5"/><rect x="21" y="14" width="6" height="30" fill="url(#gr1)" opacity=".6"/><path d="M24 14C24 14 18 6 12 8 8 10 10 14 14 14" fill="none" stroke={locked?"#aaa":"#FFD700"} strokeWidth="2.5" strokeLinecap="round"/><path d="M24 14C24 14 30 6 36 8 40 10 38 14 34 14" fill="none" stroke={locked?"#aaa":"#FFD700"} strokeWidth="2.5" strokeLinecap="round"/>{locked&&<><rect x="18" y="28" width="12" height="10" rx="2" fill="none" stroke="#aaa" strokeWidth="1.5"/><circle cx="24" cy="33" r="2" fill="#aaa"/></>}</svg>);}
function Stars({count,max=3,size=22,delay=0}){return(<div style={{display:"flex",gap:3,justifyContent:"center"}}>{Array.from({length:max},(_,i)=>(<span key={i} style={{fontSize:size,display:"inline-block",animation:i<count?`starPop .4s ease-out ${delay+i*.12}s both`:"none",filter:i<count?"drop-shadow(0 0 4px #FFD700)":"grayscale(100%) opacity(0.2)"}}>⭐</span>))}</div>);}
function VictoryBanner({score,levelName,stars,onEnd}){const[ph,setPh]=useState("in");useEffect(()=>{const t1=setTimeout(()=>setPh("out"),1600);const t2=setTimeout(onEnd,2100);return()=>{clearTimeout(t1);clearTimeout(t2);};},[onEnd]);return(<div style={{position:"fixed",inset:0,zIndex:300,display:"flex",alignItems:"center",justifyContent:"center",background:"rgba(0,0,0,.5)",backdropFilter:"blur(8px)"}}><div style={{background:"linear-gradient(145deg,rgba(15,15,15,.96),rgba(35,35,35,.96))",border:"3px solid #DAA520",borderRadius:28,padding:"36px 64px",textAlign:"center",animation:ph==="in"?"victoryIn .4s ease-out forwards":"victoryOut .4s ease-in forwards",boxShadow:"0 24px 80px rgba(0,0,0,.6)"}}><div style={{fontSize:14,fontWeight:700,color:"#DAA520",letterSpacing:3,marginBottom:10,textTransform:"uppercase"}}>{levelName} terminé</div><div style={{fontSize:56,fontWeight:900,color:"white",textShadow:ts3d,marginBottom:12}}>{score} <span style={{fontSize:18,color:"#DAA520"}}>pts</span></div><Stars count={stars} size={36} delay={.15}/><div style={{fontSize:12,color:"rgba(255,255,255,.35)",marginTop:12}}>Niveau suivant...</div></div></div>);}
