function FB({wid,n=8}){const b=useRef(Array.from({length:n},(_,i)=>{const ids=wid?[wid]:["citron","pomme","peche","fraise"];return{src:BT[ids[i%ids.length]],x:Math.random()*90+3,y:Math.random()*85+3,sz:50+Math.random()*60,d:Math.random()*4,dr:5+Math.random()*7,r:-15+Math.random()*30};})).current;return(<div style={{position:"absolute",inset:0,overflow:"hidden",pointerEvents:"none",zIndex:1}}>{b.map((b,i)=><img key={i} src={b.src} alt="" style={{position:"absolute",left:`${b.x}%`,top:`${b.y}%`,height:b.sz,objectFit:"contain",opacity:.1,transform:`rotate(${b.r}deg)`,animation:`fbt ${b.dr}s ease-in-out ${b.d}s infinite`}}/>)}</div>);}

/* Pip PROPORTIONNEL: collected/needed = 0→100% */
function Pip({collected,needed,color,dk}){if(needed<=0)return null;const p=Math.min(collected/needed*100,100);return(<div style={{width:32,display:"flex",flexDirection:"column",alignItems:"center",gap:4,flexShrink:0}}><div style={{fontSize:11,fontWeight:800,color:"white",textShadow:"0 1px 3px rgba(0,0,0,.4)"}}>{needed}</div><div style={{width:26,flex:1,minHeight:180,background:"rgba(255,255,255,.2)",borderRadius:13,position:"relative",overflow:"hidden",border:"2px solid rgba(255,255,255,.15)"}}><div style={{position:"absolute",bottom:0,width:"100%",height:`${p}%`,background:`linear-gradient(to top,${dk},${color})`,borderRadius:11,transition:"height .3s"}}/>{[25,50,75].map(v=><div key={v} style={{position:"absolute",bottom:`${v}%`,width:"100%",height:1,background:"rgba(255,255,255,.3)"}}/>)}</div><div style={{fontSize:12,fontWeight:800,color:"white",textShadow:"0 1px 3px rgba(0,0,0,.4)"}}>{collected}</div></div>);}
