function ScoreReveal({scores,onDone}){const[step,setStep]=useState(0);const[count,setCount]=useState(0);const target=(scores[WS[step]?.id]||[]).reduce((a,b)=>a+b,0);useEffect(()=>{if(step>=4){onDone();return;}const iv=setInterval(()=>{setCount(c=>{if(c>=target){clearInterval(iv);setTimeout(()=>{setStep(s=>s+1);setCount(0);},600);return target;}sfx.coin();return c+3;});},30);return()=>clearInterval(iv);},[step,target,onDone]);return(<div style={{display:"flex",gap:20,justifyContent:"center",alignItems:"flex-end",minHeight:170,flexWrap:"wrap"}}>{WS.map((w,i)=>{const vis=i<=step;const done=i<step;const pts=(scores[w.id]||[]).reduce((a,b)=>a+b,0);return(<div key={w.id} style={{textAlign:"center",opacity:vis?1:.15,transform:vis?"scale(1)":"scale(.8)",transition:"all .5s"}}><img src={BT[w.id]} alt="" style={{height:vis?80:50,objectFit:"contain",filter:vis?"drop-shadow(0 4px 12px rgba(0,0,0,.2))":"grayscale(100%)",transition:"all .5s"}}/><div style={{fontSize:24,fontWeight:900,color:"white",marginTop:4,textShadow:ts3d}}>{done?pts:i===step?count:""}</div><div style={{fontSize:12,fontWeight:700,color:"#FFD700"}}>{w.l}</div></div>);})}</div>);}

/* ROUTE MAP — contenu contenu dans le parchemin, pas de bg séparé */
function RouteMap({scores,onSelect}){
  const sts=WS.map((w,i)=>{const ws=scores[w.id]||[];const pts=ws.reduce((a,b)=>a+b,0);const done=ws.length>=3&&(w.th<=0||pts>=w.th);const locked=i>0&&!(()=>{const pw=scores[WS[i-1].id]||[];return pw.length>=3&&(WS[i-1].th<=0||pw.reduce((a,b)=>a+b,0)>=WS[i-1].th);})();return{...w,i,done,locked,active:!locked&&!done,pts,progress:ws.length/3,lvlStars:ws.map(s=>getStars(s))};});
  return(<div style={{width:"100%"}}>
    <div style={{textAlign:"center",marginBottom:20}}><img src={_logo} alt="Aris" style={{height:48,marginBottom:6}} onError={e=>{e.target.style.display='none';}}/><div style={{fontSize:22,fontWeight:900,color:"white",textShadow:ts3d}}>La Route des Saveurs</div></div>
    {sts.map((s,i)=>{const isL=i===sts.length-1;return(<div key={s.id}>
      <div onClick={()=>{if(s.active){sfx.click();onSelect(i);}}} style={{display:"flex",alignItems:"center",gap:14,padding:"14px 16px",borderRadius:18,background:s.active?"rgba(255,255,255,.88)":s.done?"rgba(255,255,255,.75)":"rgba(255,255,255,.2)",border:s.active?"2px solid #DAA520":s.done?`2px solid ${s.ac}44`:"2px solid transparent",cursor:s.active?"pointer":"default",boxShadow:s.active?"0 4px 20px rgba(218,165,32,.25)":"none"}}>
        <div style={{width:52,height:52,borderRadius:14,overflow:"hidden",flexShrink:0,border:`3px solid ${s.done?"#DAA520":s.locked?"#999":s.ac}`,opacity:s.locked?.35:1}}><img src={s.li} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/></div>
        <div style={{flex:1,opacity:s.locked?.35:1,minWidth:0}}>
          <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:2,flexWrap:"wrap"}}><span style={{fontSize:16,fontWeight:800,color:s.locked?"#999":s.dk}}>{s.l}</span>{s.done&&<TrophySVG size={18}/>}{s.active&&<span style={{fontSize:9,fontWeight:700,color:"#DAA520",background:"#DAA52012",padding:"2px 8px",borderRadius:10}}>En cours</span>}</div>
          <div style={{fontSize:11,color:"#888",marginBottom:3}}>{s.loc}</div>
          {s.done&&<div style={{display:"flex",alignItems:"center",gap:6}}><span style={{fontSize:12,fontWeight:700,color:"#DAA520"}}>{s.pts} pts</span><div style={{display:"flex",gap:1}}>{s.lvlStars.map((st,j)=><Stars key={j} count={st} max={3} size={9}/>)}</div></div>}
          {s.active&&<div style={{width:"100%",height:4,borderRadius:2,background:"#ddd",marginTop:2}}><div style={{height:"100%",borderRadius:2,background:"linear-gradient(90deg,#DAA520,#FFD700)",width:`${s.progress*100}%`}}/></div>}
        </div>
        <img src={BT[s.id]} alt="" style={{height:48,objectFit:"contain",opacity:s.locked?.25:1,filter:s.locked?"grayscale(100%)":"drop-shadow(0 2px 6px rgba(0,0,0,.12))",flexShrink:0}}/>
      </div>
      {!isL&&<div style={{display:"flex",flexDirection:"column",alignItems:"center",padding:"2px 0",marginLeft:40}}>{[0,1,2].map(j=><div key={j} style={{width:7,height:7,borderRadius:"50%",background:sts[i+1]?.locked?"#99966644":"#4CAF50",margin:"1px 0"}}/>)}</div>}
    </div>);})}
    <div style={{display:"flex",alignItems:"center",gap:12,marginTop:10,padding:"14px 16px",borderRadius:18,background:sts.every(s=>s.done)?"linear-gradient(135deg,rgba(255,215,0,.15),rgba(229,57,53,.1))":"rgba(0,0,0,.08)",border:sts.every(s=>s.done)?"2px solid #DAA520":"2px solid transparent"}}><GiftSVG size={36} locked={!sts.every(s=>s.done)}/><div style={{fontSize:14,fontWeight:800,color:sts.every(s=>s.done)?"#FFD700":"rgba(255,255,255,.5)"}}>Récompense Finale</div></div>
  </div>);
}

function StartOverlay({w,gameIdx,onStart}){return(<div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",background:"rgba(255,255,255,.93)",backdropFilter:"blur(4px)",zIndex:5,gap:12,padding:24,borderRadius:18}}><img src={BT[w.id]} alt="" style={{height:70}}/><div style={{fontSize:15,fontWeight:800,color:w.dk}}>{w.l} — {w.loc}</div><div style={{fontSize:13,color:w.tx,textAlign:"center",maxWidth:300,lineHeight:1.5,background:`${w.bgL}88`,padding:"8px 16px",borderRadius:12}}>{INSTR[gameIdx]}</div><button onClick={e=>{e.stopPropagation();sfx.init();onStart();}} style={{...btn3d(w.ac,w.dk),padding:"12px 44px",fontSize:15,marginTop:4}}>Commencer</button></div>);}

/* ═══ G1 — MIXER ═══ */
function G1({level,onDone,w}){
  const lv=Math.min(level,2);const rcp=RCP[lv];const needed=[5,7,10][lv];const dur=[45,45,30][lv];const trapRate=[.25,.35,.45][lv];const spawnMs=[1200,900,600][lv];const fallSpeed=[1.8,2.8,4][lv];const MW=14;
  const[items,setItems]=useState([]);const[col,setCol]=useState([]);const[tm,setTm]=useState(dur);const[sta,setSta]=useState(false);const[msg,setMsg]=useState(null);const[freeze,setFreeze]=useState(false);const[mx,setMx]=useState(50);
  const tid=useRef(0);const dn=useRef(false);const areaRef=useRef(null);const itemsRef=useRef([]);const mxRef=useRef(50);const freezeRef=useRef(false);const colRef=useRef([]);const tmRef=useRef(dur);
  useEffect(()=>{mxRef.current=mx;},[mx]);useEffect(()=>{freezeRef.current=freeze;},[freeze]);useEffect(()=>{colRef.current=col;},[col]);useEffect(()=>{tmRef.current=tm;},[tm]);
  useEffect(()=>{setItems([]);setCol([]);setTm(dur);setSta(false);setMsg(null);setFreeze(false);setMx(50);tid.current=0;dn.current=false;itemsRef.current=[];colRef.current=[];tmRef.current=dur;},[level]);
  useEffect(()=>{if(!sta||dn.current)return;const t=setInterval(()=>setTm(p=>{if(p<=10&&p>0)sfx.tick();if(p<=1&&!dn.current){dn.current=true;setTimeout(()=>onDone(Math.min(Math.round((colRef.current.length/needed)*83),83)),300);return 0;}return p-1;}),1000);return()=>clearInterval(t);},[sta]);
  useEffect(()=>{if(col.length>=needed&&!dn.current){dn.current=true;sfx.lvl();setTimeout(()=>onDone(Math.min(50+Math.round((tmRef.current/dur)*33),83)),300);}},[col.length]);
  useEffect(()=>{if(!sta||dn.current)return;const spawn=()=>{const id=tid.current++;const iT=Math.random()<trapRate;const it=iT?TR[Math.floor(Math.random()*TR.length)]:{...rcp.it[Math.floor(Math.random()*rcp.it.length)]};itemsRef.current=[...itemsRef.current,{id,x:5+Math.random()*80,y:-8,iT,...it,speed:fallSpeed*(.8+Math.random()*.4)}];setItems([...itemsRef.current]);};spawn();const iv=setInterval(spawn,spawnMs);return()=>clearInterval(iv);},[sta]);
  useEffect(()=>{if(!sta||dn.current)return;let af;const loop=()=>{if(dn.current)return;const upd=[];for(const it of itemsRef.current){const ny=it.y+it.speed*.35;if(ny>=82&&ny<94&&Math.abs(it.x-mxRef.current)<MW/2+4){if(!freezeRef.current){if(it.iT){sfx.trap();setFreeze(true);freezeRef.current=true;setMsg(it.m);setTimeout(()=>{setFreeze(false);freezeRef.current=false;setMsg(null);},1200);}else{sfx.grab();setCol(p=>{const n=[...p,it.n];colRef.current=n;return n;});}}continue;}if(ny>105)continue;upd.push({...it,y:ny});}itemsRef.current=upd;setItems([...upd]);af=requestAnimationFrame(loop);};af=requestAnimationFrame(loop);return()=>cancelAnimationFrame(af);},[sta]);
  const hm=useCallback(cx=>{const r=areaRef.current?.getBoundingClientRect();if(!r||freezeRef.current)return;setMx(Math.max(MW/2,Math.min(100-MW/2,((cx-r.left)/r.width)*100)));},[]);
  return(<div style={{display:"flex",gap:14,width:"100%",flex:1}}>
    <Pip collected={col.length} needed={needed} color={w.ac} dk={w.dk}/>
    <div style={{flex:1,display:"flex",flexDirection:"column",gap:10}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><span style={{fontSize:15,fontWeight:700,color:w.dk}}>🧪 {col.length}/{needed}</span><Timer tm={tm}/></div>
      <div style={{display:"flex",gap:10,flex:1}}>
        <div style={{width:120,background:"rgba(255,255,255,.9)",borderRadius:14,padding:8,flexShrink:0,border:"2px solid #DAA52022",alignSelf:"flex-start"}}>
          <div style={{fontSize:9,fontWeight:800,color:w.dk,textAlign:"center",marginBottom:3}}>RECETTE</div><img src={rcp.img} alt="" style={{width:"100%",borderRadius:8,marginBottom:4}}/>
          {rcp.it.map((ig,i)=>{const got=col.includes(ig.n);return(<div key={i} style={{display:"flex",alignItems:"center",gap:3,marginBottom:3,opacity:got?1:.35}}><img src={ig.img} alt="" style={{width:20,height:20,objectFit:"contain"}}/><span style={{fontSize:7,fontWeight:600,color:w.dk}}>{ig.n}</span>{got&&<span style={{fontSize:8,color:"#4CAF50"}}>✓</span>}</div>);})}
        </div>
        <div ref={areaRef} onClick={()=>{if(!sta){sfx.init();setSta(true);}}} onMouseMove={e=>sta&&hm(e.clientX)} onTouchMove={e=>sta&&hm(e.touches[0].clientX)} style={{flex:1,borderRadius:18,...gameGlass,position:"relative",overflow:"hidden",cursor:sta?"none":"pointer",minHeight:450,touchAction:"none"}}>
          {!sta&&<StartOverlay w={w} gameIdx={0} onStart={()=>setSta(true)}/>}{freeze&&<div style={{position:"absolute",inset:0,background:"rgba(229,57,53,.08)",zIndex:20,pointerEvents:"none"}}/>}
          {items.map(t=>(<div key={t.id} style={{position:"absolute",left:`${t.x}%`,top:`${t.y}%`,transform:"translate(-50%,-50%)",width:64,height:64,borderRadius:t.iT?14:"50%",border:t.iT?"2px solid #EF535033":`2px solid ${w.ac}33`,background:t.iT?"#fff5f5":"white",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 3px 10px rgba(0,0,0,.12)",pointerEvents:"none"}}><img src={t.img} alt="" style={{width:46,height:46,objectFit:"contain"}}/></div>))}
          {sta&&<div style={{position:"absolute",bottom:"2%",left:`${mx}%`,transform:"translateX(-50%)",width:`${MW}%`,minWidth:90,pointerEvents:"none",zIndex:10}}><svg viewBox="0 0 120 140" style={{width:"100%",filter:"drop-shadow(0 4px 14px rgba(0,0,0,.3))"}}><rect x="25" y="115" width="70" height="20" rx="6" fill="#555" stroke="#333" strokeWidth="2"/><rect x="35" y="112" width="50" height="8" rx="3" fill="#777"/><path d="M28,110 L38,20 Q40,12 50,12 L70,12 Q80,12 82,20 L92,110 Z" fill={`${w.bgL}66`} stroke={w.ac} strokeWidth="2.5"/>{col.length>0&&<><clipPath id="lc"><path d="M28,110 L38,20 Q40,12 50,12 L70,12 Q80,12 82,20 L92,110 Z"/></clipPath><rect x="20" y={110-Math.min(col.length/needed,1)*90} width="80" height={Math.min(col.length/needed,1)*90+5} fill={`${w.ac}44`} clipPath="url(#lc)"/></>}{col.slice(-4).map((n,i)=>{const it=rcp.it.find(x=>x.n===n);return it?<image key={i} href={it.img} x={35+i*14} y={85-i*12} width="18" height="18" opacity=".8"/>:null;})}<path d="M92,40 Q108,40 108,60 Q108,80 92,80" fill="none" stroke={w.ac} strokeWidth="4" strokeLinecap="round"/></svg></div>}
          {msg&&<div style={{position:"absolute",top:"40%",left:"50%",transform:"translate(-50%,-50%)",background:"rgba(198,40,40,.92)",color:"white",padding:"10px 20px",borderRadius:14,fontSize:14,fontWeight:600,zIndex:30,textAlign:"center"}}>{msg}</div>}
        </div>
      </div>
    </div>
  </div>);
}

/* ═══ G2 — Récolte SYNC early completion ═══ */
function G2({level,onDone,w}){
  const lv=Math.min(level,2);const dur=[45,45,30][lv];const sr=[800,550,350][lv];const lt=[1800,1400,1000][lv];const tc=[.25,.35,.45][lv];const needed=[12,16,22][lv];
  const[tg,setTg]=useState([]);const[sc,setSc]=useState(0);const[pn,setPn]=useState(0);const[tm,setTm]=useState(dur);const[sta,setSta]=useState(false);const[end,setEnd]=useState(false);const[msg,setMsg]=useState(null);const[freeze,setFreeze]=useState(false);
  const tid=useRef(0);const dn=useRef(false);const fi=CF[w.id]||CF.pomme;const tmRef=useRef(dur);const scRef=useRef(0);const pnRef=useRef(0);
  useEffect(()=>{tmRef.current=tm;},[tm]);
  useEffect(()=>{setTg([]);setSc(0);setPn(0);setTm(dur);setSta(false);setEnd(false);setMsg(null);setFreeze(false);tid.current=0;dn.current=false;tmRef.current=dur;scRef.current=0;pnRef.current=0;},[level]);
  useEffect(()=>{if(!sta||end)return;const t=setInterval(()=>setTm(p=>{if(p<=10&&p>0)sfx.tick();if(p<=1){setEnd(true);return 0;}return p-1;}),1000);return()=>clearInterval(t);},[sta,end]);
  useEffect(()=>{if(end&&!dn.current){dn.current=true;sfx.lvl();const n=Math.max(0,scRef.current-pnRef.current);setTimeout(()=>onDone(Math.min(Math.round((n/Math.max(needed,1))*83),83)),400);}},[end]);
  useEffect(()=>{if(!sta||end||freeze)return;const spawn=()=>{const id=tid.current++;const iT=Math.random()<tc;const tr=iT?TC[Math.floor(Math.random()*TC.length)]:null;setTg(p=>[...p,{id,x:2+Math.random()*82,y:2+Math.random()*82,iT,tr}]);setTimeout(()=>setTg(p=>p.filter(t=>t.id!==id)),lt);};spawn();const iv=setInterval(spawn,sr);return()=>clearInterval(iv);},[sta,end,freeze]);
  const catchIt=(e,t)=>{if(freeze||end||dn.current)return;e.stopPropagation();setTg(p=>p.filter(x=>x.id!==t.id));if(t.iT){sfx.trap();pnRef.current+=2;setPn(pnRef.current);setFreeze(true);setMsg(t.tr.m);setTimeout(()=>{setFreeze(false);setMsg(null);},1000);}else{sfx.grab();scRef.current+=1;setSc(scRef.current);if(scRef.current>=needed&&!dn.current){dn.current=true;setEnd(true);sfx.lvl();const bonus=Math.round((tmRef.current/dur)*33);setTimeout(()=>onDone(Math.min(50+bonus,83)),300);}}};
  return(<div style={{display:"flex",gap:14,width:"100%",flex:1}}>
    <Pip collected={sc} needed={needed} color={w.ac} dk={w.dk}/>
    <div style={{flex:1,display:"flex",flexDirection:"column",gap:10}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><div style={{display:"flex",gap:14,alignItems:"center"}}><span style={{fontSize:15,fontWeight:700,color:w.dk}}>🍎 {sc}/{needed}</span><span style={{fontSize:13,fontWeight:600,color:"#C62828"}}>💀 {pn}</span></div><Timer tm={tm}/></div>
      <div onClick={()=>{if(!sta){sfx.init();setSta(true);}}} style={{flex:1,borderRadius:20,...gameGlass,position:"relative",overflow:"hidden",cursor:"crosshair",minHeight:450}}>
        {!sta&&<StartOverlay w={w} gameIdx={1} onStart={()=>setSta(true)}/>}{freeze&&<div style={{position:"absolute",inset:0,background:"rgba(229,57,53,.08)",zIndex:20,pointerEvents:"none"}}/>}
        {tg.map(t=>(<div key={t.id} onClick={e=>catchIt(e,t)} style={{position:"absolute",left:`${t.x}%`,top:`${t.y}%`,width:58,height:58,borderRadius:t.iT?14:"50%",cursor:freeze?"not-allowed":"pointer",border:t.iT?"2px solid #EF535044":`2px solid ${w.ac}44`,transition:"transform .1s",boxShadow:"0 2px 8px rgba(0,0,0,.08)"}} onMouseEnter={e=>{if(!freeze)e.currentTarget.style.transform="scale(1.15)";}} onMouseLeave={e=>{e.currentTarget.style.transform="scale(1)";}}><img src={t.iT?t.tr.img:fi} alt="" style={{width:"100%",height:"100%",objectFit:"contain",background:t.iT?"#fafafa":"transparent"}}/></div>))}
        {msg&&<div style={{position:"absolute",bottom:14,left:"50%",transform:"translateX(-50%)",background:"rgba(198,40,40,.92)",color:"white",padding:"8px 18px",borderRadius:14,fontSize:13,fontWeight:600,zIndex:30}}>{msg}</div>}
      </div>
    </div>
  </div>);
}

function G3({level,onDone,w}){const lv=Math.min(level,2);const zs=[.3,.2,.12][lv],sp=[1.8,2.5,3.5][lv],tr=[5,5,7][lv];const[rd,setRd]=useState(0);const[pos,setPos]=useState(0);const[zst,setZst]=useState(.35);const[stp,setStp]=useState(false);const[res,setRes]=useState([]);const af=useRef(null);const pr=useRef(0);const dr=useRef(1);const dn=useRef(false);const nz=useCallback(()=>Math.random()*(1-zs)*.7+.15,[zs]);useEffect(()=>{setRd(0);setRes([]);setStp(false);pr.current=0;dr.current=1;setPos(0);setZst(nz());dn.current=false;},[level]);useEffect(()=>{if(stp||rd>=tr)return;let l=performance.now();const a=n=>{const dt=(n-l)/1000;l=n;pr.current+=dr.current*sp*dt;if(pr.current>=1){pr.current=1;dr.current=-1;}if(pr.current<=0){pr.current=0;dr.current=1;}setPos(pr.current);af.current=requestAnimationFrame(a);};af.current=requestAnimationFrame(a);return()=>cancelAnimationFrame(af.current);},[stp,rd,tr,sp]);const hs=()=>{if(stp||rd>=tr||dn.current)return;setStp(true);const iz=pos>=zst&&pos<=zst+zs;sfx.ok(iz);const nr=[...res,iz?1:Math.max(0,1-Math.min(Math.abs(pos-zst),Math.abs(pos-(zst+zs)))*4)];setRes(nr);if(nr.length>=tr){dn.current=true;sfx.lvl();setTimeout(()=>onDone(Math.min(Math.round(nr.reduce((a,b)=>a+b,0)/nr.length*83),83)),500);}else setTimeout(()=>{setStp(false);setRd(r=>r+1);setZst(nz());pr.current=0;dr.current=1;},700);};return(<div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:24,width:"100%",flex:1,...gameGlass,padding:32}}><div style={{...btn3d(w.ac,w.dk),padding:"7px 24px",fontSize:15,cursor:"default"}}>Dosage {rd+1}/{tr}</div><div style={{fontSize:13,color:w.tx,textAlign:"center",maxWidth:360}}>{INSTR[2]}</div><img src={BT[w.id]} alt="" style={{height:130,objectFit:"contain",filter:"drop-shadow(0 6px 20px rgba(0,0,0,.2))"}}/><div style={{width:"100%",maxWidth:700}}><div style={{width:"100%",height:64,borderRadius:32,background:`linear-gradient(90deg,${w.bgL},white,${w.bgL})`,border:`2px solid ${w.ac}33`,position:"relative",overflow:"hidden"}}><div style={{position:"absolute",left:`${zst*100}%`,width:`${zs*100}%`,height:"100%",background:`${w.ac}35`}}/><div style={{position:"absolute",left:`${pos*100}%`,top:"50%",transform:"translate(-50%,-50%)",width:26,height:52,borderRadius:13,background:stp?(pos>=zst&&pos<=zst+zs?w.ac:"#EF5350"):"white",border:`3px solid ${stp?(pos>=zst&&pos<=zst+zs?"#DAA520":"#C62828"):w.ac}`,boxShadow:"0 2px 10px rgba(0,0,0,.2)"}}/></div></div><button onClick={hs} disabled={stp} style={{...btn3d(stp?`${w.ac}88`:w.ac,stp?`${w.dk}88`:w.dk),padding:"18px 80px",fontSize:19}}>{stp?(pos>=zst&&pos<=zst+zs?"Parfait !":"Presque..."):"STOP"}</button></div>);}

function G4({level,onDone,w}){const lv=Math.min(level,2);const sl=[[2,3,4],[3,4,5],[5,6,7,8]][lv];const[ph,setPh]=useState("w");const[seq,setSeq]=useState([]);const[pi,setPi]=useState([]);const[ai,setAi]=useState(-1);const[sr,setSr]=useState(0);const[rr,setRr]=useState([]);const[fb,setFb]=useState(null);const dn=useRef(false);const gs=useCallback(l=>Array.from({length:l},()=>Math.floor(Math.random()*4)),[]);const ps=useCallback(s=>{setPh("w");setPi([]);setAi(-1);s.forEach((c,i)=>{setTimeout(()=>{setAi(c);sfx.sq(c);},(i+1)*600);setTimeout(()=>setAi(-1),(i+1)*600+400);});setTimeout(()=>{setPh("i");setAi(-1);},(s.length+1)*600);},[]);useEffect(()=>{setSr(0);setRr([]);setFb(null);dn.current=false;const s=gs(sl[0]);setSeq(s);ps(s);},[level]);const ar=useCallback(results=>{const n=sr+1;if(n>=sl.length&&!dn.current){dn.current=true;sfx.lvl();setTimeout(()=>onDone(Math.min(Math.round(results.reduce((x,y)=>x+y,0)/results.length*83),83)),300);}else if(n<sl.length){setSr(n);const s=gs(sl[n]);setSeq(s);ps(s);}},[sr,sl,gs,ps,onDone]);const hi=c=>{if(ph!=="i"||dn.current)return;sfx.sq(c);const n=[...pi,c];setPi(n);setAi(c);setTimeout(()=>setAi(-1),200);if(seq[n.length-1]!==c){sfx.trap();const nr=[...rr,(n.length-1)/seq.length];setRr(nr);setFb("x");setTimeout(()=>{setFb(null);ar(nr);},800);return;}if(n.length===seq.length){sfx.match();const nr=[...rr,1];setRr(nr);setFb("o");setTimeout(()=>{setFb(null);ar(nr);},800);}};return(<div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:20,width:"100%",flex:1,...gameGlass,padding:28}}><div style={{...btn3d(w.ac,w.dk),padding:"7px 24px",fontSize:15,cursor:"default"}}>Séquence {sr+1}/{sl.length}</div><div style={{fontSize:13,color:w.tx,textAlign:"center",maxWidth:360}}>{INSTR[3]}</div><img src={_fraise_b} alt="" style={{height:80,objectFit:"contain"}}/><div style={{fontSize:18,fontWeight:700,height:28,color:w.dk}}>{ph==="w"?"Observe...":fb==="o"?"Bravo !":fb==="x"?"Raté !":"A toi !"}</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:18,width:"100%",maxWidth:420}}>{SQ.map(f=>(<button key={f.id} onClick={()=>hi(f.id)} disabled={ph!=="i"} style={{height:170,borderRadius:24,border:ai===f.id?"3px solid #FFD700":"3px solid transparent",background:ai===f.id?f.c:`${f.cL}88`,cursor:ph==="i"?"pointer":"default",transition:"all .15s",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:8,fontFamily:"'Plus Jakarta Sans',sans-serif",boxShadow:ai===f.id?"0 0 24px rgba(255,215,0,.5)":"0 2px 10px rgba(0,0,0,.08)"}}><div style={{width:74,height:74,borderRadius:"50%",overflow:"hidden",border:ai===f.id?"3px solid rgba(255,255,255,.6)":`3px solid ${f.c}33`,background:ai===f.id?"rgba(255,255,255,.2)":"rgba(255,255,255,.7)",display:"flex",alignItems:"center",justifyContent:"center"}}><img src={f.img} alt="" style={{width:56,height:56,objectFit:"contain"}}/></div><span style={{fontSize:15,fontWeight:800,color:ai===f.id?"white":f.c}}>{f.n}</span></button>))}</div></div>);}

/* ═══ MAIN APP ═══ */
export default function App(){
  const[screen,setScreen]=useState("intro");const[worldIdx,setWorldIdx]=useState(0);const[levelIdx,setLevelIdx]=useState(0);const[scores,setScores]=useState({});const[introStep,setIntroStep]=useState(0);const[lastScore,setLastScore]=useState(0);const[promoShown,setPromoShown]=useState(false);const[copied,setCopied]=useState(false);const[showCf,setShowCf]=useState(false);const[revealDone,setRevealDone]=useState(false);const[vol,setVol]=useState(.5);const[mut,setMut]=useState(false);const[victoryData,setVictoryData]=useState(null);
  const nextLevelRef=useRef(0);
  const w=WS[worldIdx];const totalScore=Object.values(scores).reduce((a,ws)=>a+ws.reduce((b,s)=>b+s,0),0);const mx=WS.length*3*83;const pm=totalScore>=mx*.7?30:totalScore>=mx*.4?20:10;const cw=WS.filter(x=>{const ws=scores[x.id]||[];return ws.length>=3&&(x.th<=0||ws.reduce((a,b)=>a+b,0)>=x.th);}).length;const wsc=scores[w.id]||[];const wpts=wsc.reduce((a,b)=>a+b,0);const passed=wsc.length>=3&&(w.th<=0||wpts>=w.th);const nextW=WS[worldIdx+1];
  const IT=["Il existe en Tunisie une légende ancienne...","Quatre vergers enchantés abriteraient les saveurs les plus pures.","Citron, Pomme, Pêche, Fruits Rouges — 4 Mondes à conquérir.","Collecte les ingrédients, évite les pièges, deviens l'Explorateur ultime.","Es-tu prêt ?"];
  const handleDone=(score)=>{setLastScore(score);const ns={...scores};const ex=ns[w.id]||[];if(ex.length>=3)return;ns[w.id]=[...ex,score];setScores(ns);const nw=ns[w.id];const stars=getStars(score);if(nw.length<3){nextLevelRef.current=Math.min(nw.length,2);sfx.lvl();setVictoryData({score,levelName:`Niveau ${LV[Math.min(levelIdx,2)]}`,stars});}else{setScreen("ld");}};
  const handleVictoryEnd=useCallback(()=>{setVictoryData(null);setLevelIdx(nextLevelRef.current);setTimeout(()=>setScreen("play"),50);},[]);
  const GC=[G1,G2,G3,G4][worldIdx];const totalStarsWorld=wsc.reduce((a,s)=>a+getStars(s),0);const mustRestart=wsc.length>=3&&(worldIdx===0||worldIdx===1)&&totalStarsWorld===0&&w.th>0&&wpts<w.th;
  const showFixedLogo=screen!=="intro";

  return(<div style={{minHeight:"100vh",fontFamily:"'Plus Jakarta Sans',sans-serif",display:"flex",flexDirection:"column"}}>
    <link href={FU} rel="stylesheet"/><style>{CSS}</style>{showCf&&<Cf/>}
    {victoryData&&<VictoryBanner score={victoryData.score} levelName={victoryData.levelName} stars={victoryData.stars} onEnd={handleVictoryEnd}/>}
    {showFixedLogo&&<div style={{position:"fixed",top:14,left:18,zIndex:100}}><img src={_logo} alt="Aris" style={{height:36,filter:"drop-shadow(0 2px 6px rgba(0,0,0,.3))"}} onError={e=>{e.target.style.display='none';}}/></div>}
    <div style={{position:"fixed",top:14,right:18,zIndex:100,display:"flex",alignItems:"center",gap:8,background:"rgba(0,0,0,.35)",backdropFilter:"blur(10px)",padding:"6px 14px",borderRadius:50,border:"1px solid rgba(255,255,255,.12)"}}><button onClick={()=>{sfx.init();sfx.m=!sfx.m;setMut(!mut);}} style={{background:"none",border:"none",cursor:"pointer",display:"flex",alignItems:"center",padding:0}}><SpeakerSVG muted={mut}/></button>{!mut&&<input type="range" min="0" max="100" value={Math.round(vol*100)} onChange={e=>{const v=e.target.value/100;setVol(v);sfx.v=v;}} style={{width:56,accentColor:"#DAA520",height:4}}/>}</div>
    <div style={{flex:1,display:"flex",flexDirection:"column"}}>

      {/* INTRO — pas de logo en haut, pas de logo dans le bouton */}
      {screen==="intro"&&(<div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",position:"relative",overflow:"hidden",minHeight:"100vh"}}><NatureBg img={_bg_accueil} colorOverlay="rgba(10,31,16,.3)" darkness="rgba(0,0,0,.1)"/><div style={{position:"relative",zIndex:2,width:"100%",maxWidth:680,textAlign:"center",padding:"28px 36px",animation:"su .8s ease-out"}}><img src={_logo} alt="Aris" style={{height:65,marginBottom:14,filter:"drop-shadow(0 4px 14px rgba(0,0,0,.35))"}} onError={e=>{e.target.style.display='none';}}/><h1 style={{fontSize:48,fontWeight:900,color:"white",textShadow:ts3d,marginBottom:4}}>LA ROUTE <span style={{color:"#FFD700"}}>DES SAVEURS</span></h1><div style={{fontSize:14,fontWeight:600,color:"rgba(255,255,255,.6)",letterSpacing:2,marginBottom:32,textTransform:"uppercase"}}>4 mondes · 1 récompense</div><div style={{background:"rgba(0,0,0,.2)",backdropFilter:"blur(8px)",borderRadius:20,padding:"20px 28px",marginBottom:24,border:"1px solid rgba(255,255,255,.08)"}}><p style={{fontSize:18,lineHeight:1.7,color:"rgba(255,255,255,.92)",textShadow:"0 1px 3px rgba(0,0,0,.5)",minHeight:50}}>{IT[introStep]}</p></div><div style={{display:"flex",gap:8,justifyContent:"center",marginBottom:22}}>{IT.map((_,i)=><div key={i} style={{width:i===introStep?30:10,height:10,borderRadius:5,background:i===introStep?"#FFD700":"rgba(255,255,255,.25)",transition:"all .3s",boxShadow:i===introStep?"0 0 8px #FFD700":"none"}}/>)}</div>{introStep<IT.length-1?(<button onClick={()=>{sfx.click();setIntroStep(s=>s+1);}} style={{...btn3d("#1B5E20","#0D3B0E"),padding:"16px 56px",fontSize:16}}>Continuer</button>):(<button onClick={()=>{sfx.click();setScreen("map");}} style={{background:"linear-gradient(180deg,#E53935,#B71C1C)",border:"4px solid #DAA520",borderRadius:60,padding:"20px 72px",fontSize:26,fontWeight:900,color:"white",cursor:"pointer",fontFamily:"'Plus Jakarta Sans',sans-serif",letterSpacing:5,boxShadow:"0 6px 0 #7F0000,0 10px 24px rgba(0,0,0,.4),inset 0 2px 0 rgba(255,255,255,.2)",textShadow:"0 2px 4px rgba(0,0,0,.4)",animation:"pu 2s ease-in-out infinite"}}>JOUER</button>)}</div></div>)}

      {/* MAP — un seul bg couvre tout, contenu contenu dans le parchemin */}
      {screen==="map"&&(<div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",position:"relative",minHeight:"100vh"}}><NatureBg img={_bg_carte} darkness="rgba(0,0,0,.02)"/><div style={{position:"relative",zIndex:2,width:"100%",maxWidth:750,padding:"60px 48px 28px"}}><div style={{textAlign:"center",marginBottom:8}}><div style={{fontSize:14,color:"rgba(255,255,255,.6)",fontWeight:600}}>{cw}/4 mondes — {totalScore} pts</div></div><RouteMap scores={scores} onSelect={i=>{setWorldIdx(i);setLevelIdx((scores[WS[i].id]||[]).length);setScreen("wi");}}/></div></div>)}

      {screen==="wi"&&(<div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",position:"relative",minHeight:"100vh"}}><NatureBg img={w.bgImg} colorOverlay={w.ov} darkness="rgba(0,0,0,.1)"/><div style={{position:"relative",zIndex:2,width:"100%",maxWidth:700,textAlign:"center",padding:44,animation:"su .6s ease-out"}}><img src={BT[w.id]} alt="" style={{height:200,marginBottom:16,filter:"drop-shadow(0 10px 36px rgba(0,0,0,.3))"}}/><h2 style={{fontSize:38,fontWeight:900,color:"white",marginBottom:18,textShadow:ts3d}}>{w.l}</h2><p style={{fontSize:17,lineHeight:1.7,color:"rgba(255,255,255,.92)",background:"rgba(0,0,0,.15)",padding:"16px 24px",borderRadius:16,marginBottom:14,backdropFilter:"blur(6px)"}}>{w.st}</p><div style={{fontSize:14,color:"rgba(255,255,255,.8)",background:"rgba(0,0,0,.15)",padding:"10px 20px",borderRadius:12,marginBottom:22}}>🎮 {INSTR[worldIdx]}</div>{wsc.length>0&&<div style={{marginBottom:18}}><div style={{display:"flex",gap:10,justifyContent:"center"}}>{wsc.map((s,i)=><div key={i} style={{textAlign:"center"}}><div style={{fontSize:11,color:"rgba(255,255,255,.55)",marginBottom:3}}>Niv.{i+1}</div><Stars count={getStars(s)} size={18}/></div>)}</div></div>}<button onClick={()=>{sfx.click();setLevelIdx(Math.min(wsc.length,2));setScreen("play");}} style={{...btn3d("white","#eee"),color:w.dk,padding:"18px 60px",fontSize:17}}>Entrer dans le Verger</button></div></div>)}

      {/* PLAY — bg monde + layer blanc sur le jeu */}
      {screen==="play"&&(<div style={{flex:1,display:"flex",flexDirection:"column",position:"relative",minHeight:"100vh"}}><NatureBg img={w.bgImg} colorOverlay={w.ov} darkness="rgba(0,0,0,.08)"/><div style={{position:"relative",zIndex:2,flex:1,display:"flex",flexDirection:"column",padding:"62px 28px 24px",width:"100%",maxWidth:1100,margin:"0 auto"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><div><div style={{fontSize:12,fontWeight:700,color:"rgba(255,255,255,.6)",textTransform:"uppercase",letterSpacing:1}}>{w.l} — {w.loc}</div><div style={{fontSize:24,fontWeight:800,color:"white",textShadow:"0 1px 4px rgba(0,0,0,.3)"}}>Niveau {LV[Math.min(levelIdx,2)]}</div></div><div style={{display:"flex",alignItems:"center",gap:12}}><Stars count={0} max={3} size={18}/><div style={{...btn3d(w.ac,w.dk),padding:"6px 18px",fontSize:14,cursor:"default"}}>{Math.min(levelIdx,2)+1}/3</div></div></div><div style={{flex:1,display:"flex"}}><GC level={levelIdx} onDone={handleDone} w={w}/></div></div></div>)}

      {screen==="ld"&&(<div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:36,position:"relative",minHeight:"100vh"}}><NatureBg img={w.bgImg} colorOverlay={w.ov} darkness="rgba(0,0,0,.2)"/><div style={{position:"relative",zIndex:2,width:"100%",maxWidth:600,textAlign:"center",animation:"su .5s ease-out"}}><div style={{width:100,height:100,borderRadius:"50%",margin:"0 auto 18px",background:"rgba(255,255,255,.1)",display:"flex",alignItems:"center",justifyContent:"center",border:"3px solid #DAA520"}}><span style={{fontSize:36,fontWeight:900,color:"white",textShadow:ts3d}}>{lastScore}</span></div><Stars count={getStars(lastScore)} size={34} delay={.2}/><h3 style={{fontSize:30,fontWeight:900,color:"white",margin:"10px 0",textShadow:ts3d}}>{lastScore>70?"Exceptionnel !":lastScore>50?"Bien joué !":"Pas mal !"}</h3><div style={{display:"flex",gap:10,justifyContent:"center",marginBottom:10,flexWrap:"wrap"}}>{wsc.map((s,i)=>(<div key={i} style={{padding:"10px 18px",borderRadius:18,background:"rgba(255,255,255,.1)",textAlign:"center"}}><div style={{fontSize:12,fontWeight:700,color:"rgba(255,255,255,.8)",marginBottom:4}}>Niv.{i+1}: {s}</div><Stars count={getStars(s)} size={20}/></div>))}</div><div style={{fontSize:22,fontWeight:800,color:"white",marginBottom:24,textShadow:ts3d}}>Total: {wpts} pts {w.th>0&&<span style={{fontSize:14,color:"rgba(255,255,255,.45)"}}>/ seuil {w.th}</span>}</div>{mustRestart?(<div><div style={{fontSize:15,color:"#FFCDD2",fontWeight:700,marginBottom:14}}>Aucune étoile — recommence !</div><button onClick={()=>{setScores(prev=>({...prev,[w.id]:[]}));setLevelIdx(0);sfx.click();setTimeout(()=>setScreen("play"),50);}} style={{...btn3d(w.ac,w.dk),padding:"16px 52px",fontSize:16}}>Recommencer</button></div>):(<button onClick={()=>{sfx.click();if(passed){sfx.win();setScreen("wd");}else{sfx.fail();setScreen("wf");}}} style={{...btn3d(w.ac,w.dk),padding:"16px 52px",fontSize:16}}>Résultat</button>)}</div></div>)}

      {screen==="wf"&&(<div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:36,position:"relative",minHeight:"100vh"}}><NatureBg img={w.bgImg} darkness="rgba(0,0,0,.6)"/><div style={{position:"relative",zIndex:2,width:"100%",maxWidth:600,textAlign:"center",animation:"su .5s ease-out"}}><div style={{fontSize:60,marginBottom:14}}>😔</div><h2 style={{fontSize:32,fontWeight:900,color:"white",textShadow:ts3d,marginBottom:12}}>Seuil non atteint !</h2><p style={{fontSize:17,color:"rgba(255,255,255,.8)",marginBottom:12}}>Score: <b>{wpts}</b> / {w.th} pts</p><div style={{display:"flex",gap:8,justifyContent:"center",marginBottom:22}}>{wsc.map((s,i)=><div key={i} style={{textAlign:"center"}}><div style={{fontSize:11,color:"rgba(255,255,255,.45)"}}>Niv.{i+1}</div><Stars count={getStars(s)} size={18}/></div>)}</div><button onClick={()=>{setScores(prev=>({...prev,[w.id]:[]}));setLevelIdx(0);sfx.click();setTimeout(()=>setScreen("play"),50);}} style={{...btn3d(w.ac,w.dk),padding:"16px 52px",fontSize:16}}>Recommencer</button><br/><button onClick={()=>{sfx.click();setScreen("map");}} style={{...btn3d("rgba(255,255,255,.15)","rgba(255,255,255,.08)"),padding:"14px 44px",fontSize:14,marginTop:14,border:"2px solid rgba(255,255,255,.2)"}}>Retour</button></div></div>)}

      {screen==="wd"&&(<div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",position:"relative",minHeight:"100vh"}}><NatureBg img={w.bgImg} colorOverlay={w.ov} darkness="rgba(0,0,0,.1)"/><div style={{position:"relative",zIndex:2,width:"100%",maxWidth:600,textAlign:"center",padding:44,animation:"su .6s ease-out"}}><TrophySVG size={64}/><img src={BT[w.id]} alt="" style={{height:140,marginTop:10,marginBottom:10}}/><h2 style={{fontSize:34,fontWeight:900,color:"white",textShadow:ts3d}}>Monde {w.l} conquis !</h2><div style={{display:"flex",gap:8,justifyContent:"center",margin:"12px 0"}}>{wsc.map((s,i)=><div key={i} style={{textAlign:"center"}}><div style={{fontSize:11,color:"rgba(255,255,255,.55)"}}>Niv.{i+1}</div><Stars count={getStars(s)} size={22}/></div>)}</div><div style={{fontSize:52,fontWeight:900,color:"#FFD700",margin:"10px 0",textShadow:"0 2px 0 #8B6914,0 4px 16px rgba(0,0,0,.4)"}}>{wpts} pts</div>{nextW&&<p style={{fontSize:15,color:"rgba(255,255,255,.8)",marginBottom:18}}>{nextW.l} à {nextW.loc} débloqué !</p>}<button onClick={()=>{sfx.click();if(cw>=4)setScreen("fin");else setScreen("map");}} style={{...btn3d("white","#eee"),color:w.dk,padding:"18px 52px",fontSize:16}}>{cw>=4?"Récompense":"Retour"}</button></div></div>)}

      {screen==="fin"&&(<div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",position:"relative",minHeight:"100vh"}}><NatureBg img={_bg_accueil} darkness="rgba(0,0,0,.45)"/><div style={{position:"relative",zIndex:2,width:"100%",maxWidth:700,textAlign:"center",padding:44,animation:"su .6s ease-out"}}><TrophySVG size={80}/><h2 style={{fontSize:36,fontWeight:900,color:"white",textShadow:ts3d,marginTop:10,marginBottom:18}}>Félicitations !</h2>{!revealDone?<ScoreReveal scores={scores} onDone={()=>setRevealDone(true)}/>:<><div style={{display:"flex",gap:18,justifyContent:"center",marginBottom:22,flexWrap:"wrap"}}>{WS.map(x=>{const ws=scores[x.id]||[];return(<div key={x.id} style={{textAlign:"center"}}><img src={BT[x.id]} alt="" style={{height:70}}/><div style={{fontSize:22,fontWeight:900,color:"#FFD700",marginTop:5}}>{ws.reduce((a,b)=>a+b,0)}</div><Stars count={ws.reduce((a,s)=>a+getStars(s),0)} max={9} size={10}/></div>);})}</div><div style={{fontSize:60,fontWeight:900,color:"#FFD700",marginBottom:22,textShadow:"0 2px 0 #8B6914,0 4px 16px rgba(0,0,0,.4)"}}>{totalScore}<span style={{fontSize:20,color:"rgba(255,255,255,.5)"}}> / {mx}</span></div>{!promoShown?(<button onClick={()=>{sfx.win();setPromoShown(true);setShowCf(true);setTimeout(()=>setShowCf(false),4000);}} style={{...btn3d("#E53935","#B71C1C"),padding:"20px 70px",fontSize:19,animation:"glow 2s infinite"}}>Révéler ma Récompense</button>):(<div style={{animation:"su .5s ease-out"}}><div style={{padding:"30px 48px",borderRadius:28,background:"white",boxShadow:"0 12px 48px rgba(0,0,0,.3)",marginBottom:22,border:"3px solid #DAA520"}}><div style={{fontSize:12,fontWeight:700,color:"#DAA520",letterSpacing:3,textTransform:"uppercase",marginBottom:8}}>Code Promo Exclusif</div><div style={{fontSize:60,fontWeight:900,color:"#E53935",marginBottom:10}}>-{pm}%</div><div style={{padding:"12px 32px",borderRadius:16,background:"#FFF9C4",display:"inline-block",fontSize:22,fontWeight:800,letterSpacing:5,fontFamily:"monospace",border:"2px dashed #DAA520"}}>ARIS{pm}</div></div><div style={{display:"flex",gap:14,justifyContent:"center"}}><button onClick={()=>{navigator.clipboard?.writeText(`ARIS${pm}`);setCopied(true);setTimeout(()=>setCopied(false),2000);}} style={{...btn3d("white","#eee"),color:"#E53935",padding:"14px 38px",fontSize:15}}>{copied?"Copié !":"Copier"}</button><button onClick={()=>window.open("https://aris-icetea.tn/espace-client","_blank")} style={{...btn3d("#E53935","#B71C1C"),padding:"14px 38px",fontSize:15}}>Appliquer</button></div></div>)}</>}</div></div>)}
    </div>
    <footer style={{padding:"16px 28px",background:"linear-gradient(180deg,#1B3D1C,#0a1f10)",borderTop:"1px solid rgba(218,165,32,.15)",textAlign:"center",flexShrink:0}}><div style={{fontSize:11,color:"rgba(255,255,255,.4)",fontWeight:500}}>© 2026 Aris Ice Tea — Tous droits réservés</div></footer>
  </div>);
}
